function ending(code) {
	let base = [];
	switch (code) {
		case "A": base = ending_a(); break;
		case "B": base = ending_b(); break;
		case "C": base = ending_c(); break;
		case "E": base = ending_e(); break;
		default: base = ending_d(); break;
	}
	return [...base, ...epilogue()];
}
function epilogue() {
	let e = [wait(0.5), n("— — —")];
	if (has("louis_fled")) {
		e.push(n("Somewhere in another city a man with two ledgers walks out of a bank and doesn't look back."));
	} else if (has("louis_alive")) {
		e.push(n("Luigi stayed. His numbers now add up differently, neither in your favor nor against."));
	} else {
		e.push(n("Luigi never returned. His numbers never balanced."));
	}
	if (has("rose_has_names")) {
		e.push(n("Rose left alive. The list of names lies in someone's archives. One day it will be opened."));
	} else if (has("betrayed_rose")) {
		e.push(n("Rose no longer asks questions. She wasn't found in any of the lists."));
	}
	if (has("gave_police_list") || has("gave_ledger_police")) {
		e.push(n("A week later, men in raincoats stopped at the gate. Ruggero held your list in his hands."));
	}
	if (has("helped_wife")) {
		e.push(n("Antonio's wife received a letter with money. There was no signature. She recognized the handwriting."));
	}
	if (has("marco_ally")) {
		e.push(n("Marco no longer smiles for no reason. Sometimes he stands at your door, just because."));
	}
	if (has("ring_on_table")) {
		e.push(n("The ring remains on the tablecloth at the head of the table. No one touches it."));
	}
	if (has("told_wife")) { e.push(n("Antonio's wife heard the truth from Lucia. Since then she hasn't come to the back door.")); }
	else if (has("lied_wife")) { e.push(n("Antonio's wife is still waiting at the back door. Lucia has stopped opening the window.")); }
	if (has("knife_to_sara")) { e.push(n("The knife with the initials P. V. was once found in Sara's papers, neatly wrapped.")); }
	if (has("keeps_knife")) { e.push(n("The knife with the initials P. V. stayed with you. Sometimes it is warm.")); }
	if (has("ring_kept")) { e.push(n("The Don's ring turns warm at night. You never take it off.")); }
	if (has("protected_ruggero")) { e.push(n("Inspector Ruggero remembers that you stood between him and Sara. One day he will repay the debt.")); }
	if (has("helped_sara_ruggero")) { e.push(n("Inspector Ruggero never appeared at the back door again.")); }
	if (int(GameState.v("clumsy")) >= 4) {
		e.push(n("They say you spilled wine more often than you spoke. That, too, was remembered."));
	} else if (int(GameState.v("clumsy")) == 0) {
		e.push(n("They say you never spilled a drop. That, too, was remembered."));
	}
	return e;
}
